    actions   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
    resources = [aws_secretsmanager_secret.jwt_signing_key.arn, aws_secretsmanager_secret.notify_api_key.arn]
  }
  statement {
    sid       = "DecryptViaSecretsManagerOnly"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.secrets.arn]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["secretsmanager.${var.aws_region}.amazonaws.com"]
    }
  }
}

resource "aws_secretsmanager_secret" "jwt_signing_key" {
  name                    = "${var.environment}/${local.name}/jwt-signing-key"
  description             = "HS256 signing key for VulnTracker access tokens (>= 32 random bytes)"
  kms_key_id              = aws_kms_key.secrets.arn
  recovery_window_in_days = 30
}

resource "aws_secretsmanager_secret" "notify_api_key" {
  name                    = "${var.environment}/${local.name}/notify-api-key"
  description             = "Bearer key the API presents to the notification service"
  kms_key_id              = aws_kms_key.secrets.arn
  recovery_window_in_days = 30
}

resource "kubernetes_deployment_v1" "api" {
  # checkov:skip=CKV_K8S_14:False positive - var.image is validated to be repo@sha256:<digest>; checkov cannot resolve variables
  # checkov:skip=CKV_K8S_43:False positive - var.image is validated to be repo@sha256:<digest>; checkov cannot resolve variables
  metadata {
    name      = local.name
    namespace = kubernetes_namespace_v1.this.metadata[0].name
    labels    = { app = local.name }
  }

  spec {
    replicas = var.replicas
    strategy {
      # SQLite on a single volume cannot run two writers; switch to RollingUpdate
      # once DATABASE_URL points to a managed database.
      type = "Recreate"
    }
    selector {
      match_labels = { app = local.name }
    }

    template {
      metadata {
        labels = { app = local.name }
      }

      spec {
        service_account_name            = kubernetes_service_account_v1.api.metadata[0].name
        automount_service_account_token = false
        enable_service_links            = false

        security_context {
          run_as_non_root = true
          run_as_user     = 10001
          run_as_group    = 10001
          fs_group        = 10001
          seccomp_profile {
            type = "RuntimeDefault"
          }
        }

        container {
          name              = "api"
          image             = var.image # digest-pinned (validated)
          image_pull_policy = "Always"

          port {
            name           = "http"
            container_port = 8000
            protocol       = "TCP"
          }

          # Non-secret configuration only. Secrets are referenced by *file path*.
          env {
            name  = "APP_ENV"
            value = "production"
          }
          env {
            name  = "JWT_SECRET_KEY_FILE"
            value = "/mnt/secrets/jwt_secret_key"
          }
          env {
            name  = "NOTIFY_API_KEY_FILE"
            value = "/mnt/secrets/notify_api_key"
          }
          env {
            name  = "NOTIFY_SERVICE_URL"
            value = "http://vulntracker-notify.${var.namespace}.svc.cluster.local:3001"
          }
          env {
            name  = "PUBLIC_BASE_URL"
            value = "https://${var.public_hostname}"
          }
          env {
            name  = "CORS_ALLOWED_ORIGINS"
            value = var.cors_allowed_origins
          }

          resources {
            requests = {
              cpu               = "100m"
              memory            = "128Mi"
              ephemeral-storage = "64Mi"
            }
            limits = {
              cpu               = "500m"
              memory            = "256Mi"
              ephemeral-storage = "256Mi"
            }
          }

          security_context {
            allow_privilege_escalation = false
            privileged                 = false
            read_only_root_filesystem  = true
            run_as_non_root            = true
            run_as_user                = 10001
            capabilities {
              drop = ["ALL"]
            }
          }

          liveness_probe {
            http_get {
              path = "/health"
              port = "http"
            }
            initial_delay_seconds = 10
            period_seconds        = 20
          }
          readiness_probe {
            http_get {
              path = "/health"
              port = "http"
            }
            period_seconds = 10
          }

          volume_mount {
            name       = "secrets"
            mount_path = "/mnt/secrets"
            read_only  = true
          }
          volume_mount {
            name       = "data"
            mount_path = "/app/data"
          }
          volume_mount {
            name       = "tmp"
            mount_path = "/tmp"
          }
        }

        volume {
          name = "secrets"
          csi {
            driver            = "secrets-store.csi.k8s.io"
            read_only         = true
            volume_attributes = {
              secretProviderClass = kubernetes_manifest.secret_provider_class.manifest.metadata.name
            }
          }
        }
        volume {
          name = "data"
          persistent_volume_claim {
            claim_name = kubernetes_persistent_volume_claim_v1.data.metadata[0].name
          }
        }
        volume {
          name = "tmp"
          empty_dir {
            medium     = "Memory"
            size_limit = "16Mi"
          }
        }
      }
    }
  }
}

